// Regenerates docs/DATA_DICTIONARY.md and docs/METRIC_DICTIONARY.md from the code that enforces them.
import { writeFileSync } from "node:fs";
import { DICTIONARY } from "../shared/fields";
import { ENTITY_TYPES, product } from "../shared/catalog";
import { MODULES } from "../server/modules";
const esc = (s: string) => s.replaceAll("|", "\\|");
let d =
  "# Data dictionary\n\nGenerated by `npm run docs` from `shared/fields.ts`. Required fields reject the row when missing; optional fields unlock additional analyses (see each report's capability checklist). Empty values stay empty (null), never zero. Timestamps need a timezone (`Z` or `±hh:mm`); dates use `YYYY-MM-DD`. Lists use `;`. Blank CSV templates: Data & connections → Download template.\n";
for (const app of ["eloqua", "unity", "infinity"] as const) {
  d += `\n## ${product(app).name}\n`;
  for (const t of ENTITY_TYPES[app]) {
    d += `\n### ${t}\n\n| Field | Type | Required | Meaning |\n|---|---|---|---|\n`;
    for (const f of DICTIONARY[t])
      d += `| \`${f.name}\` | ${f.type}${f.unit ? ` (${f.unit})` : ""} | ${f.required ? "yes" : ""} | ${esc(f.description)} |\n`;
  }
}
writeFileSync("docs/DATA_DICTIONARY.md", d);
let m =
  "# Metric and rule dictionary\n\nGenerated by `npm run docs` from the product modules. Numbers are calculated by deterministic code with exact decimals; the AI never produces them. Portfolio rates aggregate numerators and denominators; they are never averages of percentages.\n";
for (const app of ["eloqua", "unity", "infinity"] as const) {
  const mod = MODULES[app];
  m += `\n## ${product(app).name} (${mod.definitionVersion})\n\n### Metrics\n\n| ID | Metric | Grain | Basis | Numerator | Denominator | Time basis | Exclusions / caveats |\n|---|---|---|---|---|---|---|---|\n`;
  for (const x of mod.metricDictionary)
    m += `| \`${x.id}\` | ${esc(x.label)} | ${x.grain} | ${x.basis} | ${esc(x.numerator)} | ${esc(x.denominator || "—")} | ${esc(x.timeBasis)} | ${esc(x.exclusions)} |\n`;
  m += `\n### Assessment rules\n\n| Rule | Severity | Automation | Owner | Description | Measurement |\n|---|---|---|---|---|---|\n`;
  for (const [id, r] of Object.entries(mod.rules))
    m += `| \`${id}-${r.version}\` | ${r.severity} | ${r.automation} | ${esc(r.ownerRole)} | ${esc(r.description)} | ${esc(r.measurement)} |\n`;
  m += `\n### Scenario inputs\n\n${mod.scenarioFields.map((f) => `- ${f.label}${f.prefill ? ` (prefilled from \`${f.prefill}\` when measured)` : " (your assumption)"}`).join("\n")}\n`;
}
m +=
  "\n## Default rule thresholds (editable per source policy)\n\n| Key | Default | Used by |\n|---|---|---|\n| minSends | 100 | Eloqua campaign rules apply only above this volume |\n| bounceRateThreshold | 5 % | Eloqua bounce rule |\n| unsubscribeRateThreshold | 0.5 % | Eloqua unsubscribe rule |\n| ctorGapPp | 5 pp | Eloqua click-to-open gap vs portfolio |\n| activityLookbackDays | 3 | Eloqua immature (delayed) activity |\n| attributionWindowDays | 7 | Eloqua click-to-form window |\n| exposureMaxSends / exposureWindowDays | none (must be approved) | Eloqua exposure flag |\n| deliveryFromBounces | false | Derive delivered = sends − bounces only when approved |\n| minCohort | 30 | Minimum entities before drop-off rules apply |\n| dropThreshold | 30 % | Eloqua nurture / click-to-form, Infinity journey drop-off |\n| requiredFields | [] (must be chosen) | Unity completeness |\n| staleDays | 30 | Unity record freshness; report staleness banner |\n| snapshotToleranceHours | 1 | Unity exact overlap compatibility |\n| conversionEvent | none (must be named) | Infinity event conversion |\n| funnelSteps / funnelWindowMinutes / funnelIdentity | none / 30 / session | Infinity journey |\n| lateMinutes | 60 | Infinity late events |\n| minHistoryDays / anomalyZ | 14 / 3 | Infinity volume anomaly |\n";
writeFileSync("docs/METRIC_DICTIONARY.md", m);
console.log(
  "docs/DATA_DICTIONARY.md and docs/METRIC_DICTIONARY.md regenerated",
);
